<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { VueFlow } from '@vue-flow/core'
import type { Node as GraphNode, Edge } from '@vue-flow/core'
import TracePlot from './TracePlot.vue'
import { port, queue } from './types'
import type { Scenario, Device, Flow } from './types'
const scenario=ref<Scenario>({schema_version:1,name:'New scenario',nodes:[],links:[],flows:[],experiment:{duration:1.1,warmup:0,seed:1}})
const templates=ref<Scenario[]>([]), revisions=ref<any[]>([]), jobs=ref<any[]>([]), capabilities=ref<any>({features:{}})
const active=ref('Topology'), selected=ref(''), result=ref<any>(null), job=ref<any>(null), message=ref(''), busy=ref(false), file=ref('omnetpp.ini')
const graphNodes=ref<GraphNode[]>([]), history=ref<string[]>([]), future=ref<string[]>([])
const flowId=ref(''), trace=ref(''), chosenRevision=ref(''), chosenTemplate=ref('0'), compareId=ref(''), compared=ref<any>(null)
const linkDraft=ref({source:'',target:'',sourcePort:0,targetPort:0})
const devices=computed(()=>scenario.value.nodes.filter(n=>n.kind==='device'))
const chosen=computed(()=>scenario.value.nodes.find(n=>n.id===selected.value))
const chosenFlow=computed(()=>scenario.value.flows.find(f=>f.id===flowId.value))
const metrics=computed(()=>job.value?.metrics)
const finished=new Set(['completed','failed','cancelled','interrupted'])
let timer:ReturnType<typeof setInterval>|undefined
async function api(path:string, body?:unknown){
 const response=await fetch('/api/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
 const data=await response.json(); if(!response.ok)throw new Error(data.diagnostics?JSON.stringify(data.diagnostics,null,2):data.error||response.statusText);return data
}
function snapshot(){history.value.push(JSON.stringify(scenario.value));history.value=history.value.slice(-40);future.value=[]}
function syncGraph(){graphNodes.value=scenario.value.nodes.map(n=>({id:n.id,label:n.id+' · '+(n.kind==='switch'?'TSN switch':'End device'),position:{x:n.x,y:n.y},class:n.kind}))}
function restore(s:Scenario){snapshot();scenario.value=JSON.parse(JSON.stringify(s));selected.value='';result.value=null;syncGraph()}
function undo(){if(!history.value.length)return;future.value.push(JSON.stringify(scenario.value));scenario.value=JSON.parse(history.value.pop()!);syncGraph()}
function redo(){if(!future.value.length)return;history.value.push(JSON.stringify(scenario.value));scenario.value=JSON.parse(future.value.pop()!);syncGraph()}
const edges=computed<Edge[]>(()=>scenario.value.links.map(l=>({id:l.id,source:l.a.node,target:l.b.node,label:`eth${l.a.port} ↔ eth${l.b.port} · ${l.bitrate/1e6} Mbps`,animated:!!result.value?.paths?.[flowId.value]?.some((h:any)=>h.node===l.a.node&&h.port===l.a.port||h.node===l.b.node&&h.port===l.b.port)})))
function unique(prefix:string,items:{id:string}[]){let i=0;while(items.some(n=>n.id===prefix+i))i++;return prefix+i}
function addNode(kind:'device'|'switch') {snapshot();const n:Device={id:unique(kind==='device'?'host':'sw',scenario.value.nodes),kind,ports:[port(0)],x:100+(scenario.value.nodes.length%4)*210,y:100+Math.floor(scenario.value.nodes.length/4)*120};scenario.value.nodes.push(n);selected.value=n.id;syncGraph()}
function removeNode(){snapshot();const id=selected.value;scenario.value.nodes=scenario.value.nodes.filter(n=>n.id!==id);scenario.value.links=scenario.value.links.filter(l=>l.a.node!==id&&l.b.node!==id);scenario.value.flows=scenario.value.flows.filter(f=>f.source!==id&&f.destination!==id);selected.value='';syncGraph()}
function duplicateNode(){if(!chosen.value)return;snapshot();const n=JSON.parse(JSON.stringify(chosen.value));n.id=unique(n.kind==='device'?'host':'sw',scenario.value.nodes);n.x+=40;n.y+=60;scenario.value.nodes.push(n);syncGraph()}
function addLink(){snapshot();scenario.value.links.push({id:unique('link',scenario.value.links),a:{node:linkDraft.value.source,port:linkDraft.value.sourcePort},b:{node:linkDraft.value.target,port:linkDraft.value.targetPort},bitrate:100000000,delay:0.000001})}
function addFlow(){snapshot();const f:Flow={id:unique('flow',scenario.value.flows),source:devices.value[0]?.id||'',destination:devices.value.at(-1)?.id||'',payload:1000,interval:.001,start:0,stop:1,vlan:10,pcp:4,deadline:.01};scenario.value.flows.push(f);flowId.value=f.id}
function move(event:any){snapshot();const n=scenario.value.nodes.find(n=>n.id===event.node.id);if(n){n.x=event.node.position.x;n.y=event.node.position.y}}
async function action(fn:()=>Promise<void>){busy.value=true;message.value='';try{await fn()}catch(e){message.value=String(e)}finally{busy.value=false}}
async function compile(){result.value=await api('compile',scenario.value);message.value='Validated and generated. '+result.value.diagnostics.length+' warnings.'}
async function refresh(){jobs.value=await api('jobs');if(job.value){job.value=await api('jobs/'+job.value.id)}}
async function run(){await compile();const response=await api('jobs',{scenario:scenario.value});job.value=await api('jobs/'+response.id);active.value='Runs';await refresh()}
async function copyCommand(){
 if(!job.value)return
 await navigator.clipboard.writeText(job.value.command)
 message.value='Command copied'
}
async function save(){const saved=await api('scenarios',scenario.value);revisions.value=await api('scenarios');chosenRevision.value=saved.id;message.value='Saved immutable revision '+saved.id.slice(0,8)}
async function exportBundle(){const r=await fetch('/api/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(scenario.value)});if(!r.ok)throw new Error(await r.text());download(await r.blob(),'tsn-scenario.zip')}
function download(blob:Blob,name:string){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function jsonExport(){download(new Blob([JSON.stringify(scenario.value,null,2)],{type:'application/json'}),'scenario.json')}
async function importFile(e:Event){const input=e.target as HTMLInputElement;const f=input.files?.[0];if(!f)return;await action(async()=>{const s=JSON.parse(await f.text());await api('compile',s);restore(s);message.value='Imported scenario'});input.value=''}
function csvExport(){const rows=[['flow','generated','received','missing_at_horizon','deadline_misses','mean_latency_s','p99_latency_s','mean_absolute_ipdv_s','goodput_bps'],...Object.entries(metrics.value.flows).map(([id,m]:[string,any])=>[id,m.generated,m.received,m.missing_at_horizon,m.deadline_misses,m.latency_seconds.mean,m.latency_seconds.p99,m.mean_absolute_ipdv_seconds,m.goodput_bps])];download(new Blob([rows.map(row=>row.map(v=>JSON.stringify(v??'')).join(',')).join('\n')],{type:'text/csv'}),'metrics.csv')}
const format=(value:number|null,scale=1)=>value==null?'—':(value*scale).toFixed(3)
const latencySamples=computed(()=>metrics.value?.flows?.[flowId.value]?.latency_trace?.map((p:any)=>[p.time,p.delay*1e6])||[])
const cdf=computed(()=>{const a=latencySamples.value.map((p:number[])=>p[1]).sort((a:number,b:number)=>a-b);return a.map((v:number,i:number)=>[v,(i+1)/a.length])})
const queueSamples=computed(()=>trace.value===''?[]:metrics.value?.traces?.[Number(trace.value)]?.samples||[])
watch(scenario,()=>{result.value=null;localStorage.setItem('tsn-draft',JSON.stringify(scenario.value))},{deep:true})
onMounted(()=>action(async()=>{templates.value=await api('templates');capabilities.value=await api('capabilities');revisions.value=await api('scenarios');const draft=localStorage.getItem('tsn-draft');if(draft){try{scenario.value=JSON.parse(draft)}catch{scenario.value=JSON.parse(JSON.stringify(templates.value[0]))}}else scenario.value=JSON.parse(JSON.stringify(templates.value[0]));syncGraph();await refresh();timer=setInterval(()=>refresh().catch(()=>{}),1500)}))
onUnmounted(()=>clearInterval(timer))
</script>

<template>
<div class="shell">
 <aside class="rail"><div class="brand">◈ <strong>TSN<span>LAB</span></strong></div><div class="eyebrow">SCENARIO WORKSPACE</div><button v-for="tab in ['Topology','Traffic','Features','Generated files','Runs','Results']" :key="tab" :class="{selected:active===tab}" @click="active=tab">{{tab}}</button><div class="rail-footer"><span class="dot"></span> Cmdenv only<br><small>OMNeT++ 6.4 · INET 4.7</small></div></aside>
 <main>
 <header><div><div class="eyebrow">ETHERNET / CREDIT-BASED SHAPING</div><input class="title" aria-label="Scenario name" v-model="scenario.name"><p class="muted">Build a network. Freeze its traffic. Evaluate the outcome.</p></div><div class="actions"><button @click="action(save)" :disabled="busy">Save revision</button><button @click="action(compile)" :disabled="busy">Validate</button><button class="primary" @click="action(run)" :disabled="busy">▶ Run simulation</button></div></header>
 <section class="summary"><div><strong>{{scenario.nodes.length}}</strong> Nodes</div><div><strong>{{scenario.links.length}}</strong> Links</div><div><strong>{{scenario.flows.length}}</strong> Traffic flows</div><div><strong>{{scenario.experiment.seed}}</strong> Simulation seed</div><div class="badge">HEADLESS EXECUTION</div></section>
 <p v-if="message" role="status" class="notice">{{message}}</p>
 <div class="toolbar"><select aria-label="Template" v-model="chosenTemplate"><option v-for="(t,i) in templates" :value="String(i)">{{t.name}}</option></select><button @click="restore(templates[Number(chosenTemplate)])">Load template</button><select aria-label="Saved revision" v-model="chosenRevision"><option value="">Saved revisions</option><option v-for="r in revisions" :value="r.id">{{JSON.parse(r.body).name}} · {{r.id.slice(0,8)}}</option></select><button :disabled="!chosenRevision" @click="restore(JSON.parse(revisions.find(r=>r.id===chosenRevision).body))">Open</button><button @click="jsonExport">Export JSON</button><label class="button">Import JSON<input type="file" accept=".json" hidden @change="importFile"></label></div>
 <section v-if="active==='Topology'" class="editor">
  <div class="canvas-panel"><div class="toolbar"><button @click="addNode('device')">+ End device</button><button @click="addNode('switch')">+ Switch</button><select aria-label="Highlight flow path" v-model="flowId"><option value="">Highlight flow path</option><option v-for="f in scenario.flows" :value="f.id">{{f.id}}</option></select><button @click="undo" :disabled="!history.length">Undo</button><button @click="redo" :disabled="!future.length">Redo</button></div><VueFlow v-model:nodes="graphNodes" :edges="edges" :nodes-connectable="false" :delete-key-code="null" fit-view-on-init @node-click="({node})=>selected=node.id" @node-drag-stop="move"/><div class="canvas-help">Select a node to configure ports · Drag to arrange · Scroll to zoom</div></div>
  <div class="inspector"><h2>{{chosen?.id || 'Network inspector'}}</h2><template v-if="chosen"><p class="muted">{{chosen.kind==='switch'?'TSN Ethernet switch':'TSN end device'}}</p><div class="actions"><button @click="duplicateNode">Duplicate</button><button class="danger" @click="removeNode">Delete</button></div><h3>Ethernet ports</h3><button v-if="chosen.kind==='switch'" @click="snapshot();chosen.ports.push(port(chosen.ports.length))">+ Port</button><article v-for="p in chosen.ports" :key="p.index"><h3>eth{{p.index}}</h3><label>Ingress / egress permitted VLANs<input :value="p.vlans.join(',')" @change="p.vlans=($event.target as HTMLInputElement).value.split(',').map(Number)"></label><p class="muted">Tagged traffic admission. IDs 1–4094.</p><h4>PCP → traffic class</h4><div class="pcp"><label v-for="(_,i) in p.pcp_map">{{i}}<select v-model.number="p.pcp_map[i]"><option v-for="(_,c) in p.queues" :value="c">{{c}}</option></select></label></div><h4>Egress classes · larger index first</h4><article v-for="(q,i) in p.queues"><b>Class {{i}}</b><select aria-label="Shaper" v-model="q.shaper"><option value="sp">Strict priority / FIFO</option><option value="cbs">CBS / FIFO</option></select><label>Queue capacity (packets)<input type="number" min="1" v-model.number="q.capacity"></label><label v-if="q.shaper==='cbs'">idleSlope (bits/s)<input type="number" min="1" v-model.number="q.idle_slope"></label><label v-if="q.shaper==='cbs'" class="check"><input type="checkbox" v-model="q.optimize">Expose to future optimizer</label></article><button :disabled="p.queues.length>=8" @click="p.queues.push(queue())">+ Class</button><button :disabled="p.queues.length<=1" @click="p.queues.pop()">Remove last class</button></article></template><p v-else class="muted">Select a node on the canvas. End devices generate and receive traffic; switch ports classify and shape it.</p></div>
 </section>
 <section v-if="active==='Topology'" class="panel"><h2>Ethernet links</h2><div class="toolbar"><select aria-label="Source node" v-model="linkDraft.source"><option value="">Source node</option><option v-for="n in scenario.nodes">{{n.id}}</option></select><input aria-label="Source port" type="number" min="0" v-model.number="linkDraft.sourcePort"><span>↔</span><select aria-label="Target node" v-model="linkDraft.target"><option value="">Target node</option><option v-for="n in scenario.nodes">{{n.id}}</option></select><input aria-label="Target port" type="number" min="0" v-model.number="linkDraft.targetPort"><button @click="addLink" :disabled="!linkDraft.source||!linkDraft.target">+ Connect</button></div><table><thead><tr><th>Link</th><th>Endpoints</th><th>Rate (bits/s)</th><th>Delay (s)</th><th></th></tr></thead><tbody><tr v-for="(l,i) in scenario.links"><td>{{l.id}}</td><td>{{l.a.node}}:eth{{l.a.port}} ↔ {{l.b.node}}:eth{{l.b.port}}</td><td><input type="number" min="1" v-model.number="l.bitrate"></td><td><input type="number" min="0" step="0.000001" v-model.number="l.delay"></td><td><button @click="snapshot();scenario.links.splice(i,1)">Remove</button></td></tr></tbody></table></section>
 <section v-if="active==='Traffic'" class="panel"><div class="section-title"><div><h2>Traffic flows</h2><p class="muted">Periodic unicast UDP · payload excludes network headers · one receiving socket per flow</p></div><button @click="addFlow">+ Flow</button></div><article v-for="(f,i) in scenario.flows" :key="f.id"><div class="section-title"><input aria-label="Flow ID" v-model="f.id"><button @click="snapshot();scenario.flows.splice(i,1)">Remove flow</button></div><div class="form-grid"><label>Source<select v-model="f.source"><option v-for="n in devices">{{n.id}}</option></select></label><label>Destination<select v-model="f.destination"><option v-for="n in devices">{{n.id}}</option></select></label><label>Payload (bytes)<input type="number" min="1" max="1472" v-model.number="f.payload"></label><label>Interval (s)<input type="number" min="0.00000001" step="0.0001" v-model.number="f.interval"></label><label>VLAN<input type="number" min="1" max="4094" v-model.number="f.vlan"></label><label>PCP<input type="number" min="0" max="7" v-model.number="f.pcp"></label><label>Start (s)<input type="number" min="0" v-model.number="f.start"></label><label>Stop (s)<input type="number" min="0" v-model.number="f.stop"></label><label>Deadline (s)<input type="number" min="0" step="0.001" v-model.number="f.deadline"></label></div></article></section>
 <section v-if="active==='Features'" class="panel"><h2>Validated feature profile</h2><p>Tagged IPv4/UDP on acyclic Ethernet topologies. CBS and strict priority can be mixed per egress port.</p><div class="feature-grid"><div v-for="(supported,name) in capabilities.features"><b>{{String(name).replaceAll('_',' ')}}</b><span :class="supported?'enabled':'muted'">{{supported?'Supported':'Planned · unavailable'}}</span></div></div><p class="muted">Ingress VLAN admission is available. Buffered ingress priority queues require a separate model; enabling CBS configures egress queues.</p></section>
 <section v-if="active==='Generated files'" class="panel"><div class="section-title"><h2>Simulation bundle</h2><div class="actions"><button @click="action(compile)">Generate / refresh</button><button @click="action(exportBundle)">Download ZIP</button></div></div><template v-if="result"><select aria-label="Generated file" v-model="file"><option v-for="(_,name) in result.files">{{name}}</option></select><pre>{{result.files[file]}}</pre><h3>Resolved flow paths</h3><div v-for="(hops,id) in result.paths"><b>{{id}}</b><p>{{hops.map((h:any)=>`${h.node}:eth${h.port} → class ${h.traffic_class}`).join(' / ')}}</p></div></template><p v-else class="muted">Generate to validate the scenario and inspect deterministic NED, INI, manifest and path mappings.</p></section>
 <section v-if="active==='Runs'" class="panel"><h2>Simulation jobs</h2><table><thead><tr><th>Job</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><tr v-for="r in jobs"><td>{{r.id.slice(0,8)}}</td><td>{{r.status}}</td><td>{{new Date(r.created*1000).toLocaleString()}}</td><td><button @click="action(async()=>{job=await api('jobs/'+r.id)})">Inspect</button></td></tr></tbody></table><template v-if="job"><h3>{{job.id}} · {{job.status}}</h3><p class="notice" v-if="job.error">{{job.error}}</p><div class="actions"><button v-if="!finished.has(job.status)" @click="action(async()=>{await api('jobs/'+job.id+'/cancel',{});await refresh()})">Cancel run</button><button @click="action(copyCommand)">Copy command</button><a :href="'/api/jobs/'+job.id+'/artifacts'">Download artifacts</a><button v-if="job.metrics" @click="active='Results'">View results</button></div><pre>{{job.command}}</pre><pre class="log">{{job.log||'Waiting for worker…'}}</pre></template><p v-else class="muted">Run a simulation or select an existing job. Every evaluation preserves its own immutable scenario and output directory.</p></section>
 <section v-if="active==='Results'" class="panel"><h2>Evaluation results</h2><template v-if="metrics"><div class="actions"><button @click="csvExport">Export metrics CSV</button><a :href="'/api/jobs/'+job.id+'/artifacts'">Full artifacts</a><select aria-label="Compare run" v-model="compareId"><option value="">Compare completed run</option><option v-for="r in jobs.filter(j=>j.status==='completed')" :value="r.id">{{r.id.slice(0,8)}}</option></select><button :disabled="!compareId" @click="action(async()=>{compared=await api('jobs/'+compareId)})">Compare</button></div><p class="muted">Delays in µs · missing packets are measured at the observation horizon, not confirmed network drops.</p><table><thead><tr><th>Flow</th><th>Sent / received</th><th>Missing</th><th>Deadline misses</th><th>Mean / p99 latency (µs)</th><th>Mean |IPDV| (µs)</th></tr></thead><tbody><tr v-for="(m,id) in metrics.flows" @click="flowId=String(id)"><td><button @click="flowId=String(id)">{{id}}</button></td><td>{{m.generated}} / {{m.received}}</td><td>{{m.missing_at_horizon}}</td><td>{{m.deadline_misses}} / {{m.deadline_denominator}}</td><td>{{format(m.latency_seconds.mean,1e6)}} / {{format(m.latency_seconds.p99,1e6)}}</td><td>{{format(m.mean_absolute_ipdv_seconds,1e6)}}</td></tr></tbody></table><select aria-label="Flow plot" v-model="flowId"><option value="">Select flow to plot</option><option v-for="(_,id) in metrics.flows">{{id}}</option></select><TracePlot :samples="latencySamples" label="Application end-to-end latency (µs) over time (s)"/><TracePlot :samples="cdf" label="Latency CDF · x: latency (µs), y: cumulative probability"/><select aria-label="Queue trace" v-model="trace"><option value="">Select queue / CBS trace</option><option v-for="(t,i) in metrics.traces" :value="String(i)">{{t.module}} · {{t.name}}</option></select><TracePlot :samples="queueSamples" label="Queue / CBS diagnostic trace · original signal units"/><template v-if="compared?.metrics"><h3>Comparison · {{compared.id.slice(0,8)}}</h3><pre>{{JSON.stringify(Object.fromEntries(Object.entries(compared.metrics.flows).map(([id,m]:[string,any])=>[id,{mean_latency_s:m.latency_seconds.mean,missing:m.missing_at_horizon,deadline_misses:m.deadline_misses}])),null,2)}}</pre></template></template><p v-else class="muted">Select a completed run in Runs. Failed or incomplete jobs do not produce final metrics.</p></section>
 <footer class="panel"><h3>Experiment settings</h3><div class="form-grid"><label>Simulation end (s)<input type="number" step="0.1" min="0" v-model.number="scenario.experiment.duration"></label><label>Warm-up (s)<input type="number" step="0.1" min="0" v-model.number="scenario.experiment.warmup"></label><label>Seed<input type="number" min="0" v-model.number="scenario.experiment.seed"></label></div><p class="muted">Stop traffic before the simulation ends to allow delivery and deadline accounting. Saved jobs retain their own settings.</p></footer>
 </main>
</div>
</template>
